@@ -35,6 +35,10 @@ const maxDiagnostic = 262_144
 // resetMarker opens the content of a working-window reset message.
 const resetMarker = "Local working-window reset\n"

+// resetHistoryListed is how many archive references a reset message lists in full: the new
+// archive and the ones before it.
+const resetHistoryListed = 8
+
 func contextUnavailable() *sys.Error {
 	return sys.Fail("intent", "context_unavailable",
 		"expected bounded nonblank UTF-8 diagnostic data with an absolute source label and matching SHA-256", 2)
@@ -274,12 +278,18 @@ func (b *Attempt) prepareContext(owner string, role project.Role, instructions s
 		}
 		w.archive = append(archive, '\n')
 		w.history = append(slices.Clone(state.History), HistoryRef{Path: path, SHA256: core.HashHex(w.archive)})
-		refs := make([]any, 0, len(w.history))
+		// The message lists the new archive and the archives before it up to resetHistoryListed in
+		// all; older ones stay in native custody (w.history keeps every reference).
+		listed, omitted := w.history, []HistoryRef(nil)
+		if len(listed) > resetHistoryListed {
+			listed, omitted = listed[len(listed)-resetHistoryListed:], listed[:len(listed)-resetHistoryListed]
+		}
+		refs := make([]any, 0, len(listed))
 		inCatalog := 0
-		for i, h := range w.history {
+		for i, h := range listed {
 			ref := map[string]any{"path": h.Path, "sha256": h.SHA256}
 			// The new archive is always carried.
-			if encoded, err := core.EncodeJSON(ref); i < len(state.History) && err == nil && listedIn(mandatoryText, string(encoded)) {
+			if encoded, err := core.EncodeJSON(ref); i < len(listed)-1 && err == nil && listedIn(mandatoryText, string(encoded)) {
 				inCatalog++
 				continue
 			}
